const state={events:[],filtered:[],month:new Date(),format:'All',topic:'',query:'',weekEvents:[],slideIndex:0,slideTimer:null};
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>\"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
const dateOnly=value=>value.length===10;
const dateOf=value=>new Date(dateOnly(value)?value+'T12:00:00':value);
const fmt=(value,options={})=>new Intl.DateTimeFormat('en-NL',{day:'numeric',month:'short',year:'numeric',...options}).format(dateOf(value));
function sameDay(left,right){return left.getFullYear()===right.getFullYear()&&left.getMonth()===right.getMonth()&&left.getDate()===right.getDate()}
function weekStart(value){const date=new Date(value);date.setHours(0,0,0,0);date.setDate(date.getDate()-((date.getDay()+6)%7));return date}
function addDays(value,days){const date=new Date(value);date.setDate(date.getDate()+days);return date}
function eventsInWeek(events,start){const end=addDays(start,7);return events.filter(event=>dateOf(event.start)<end&&dateOf(event.end||event.start)>=start).sort((left,right)=>dateOf(left.start)-dateOf(right.start))}
function selectFeatureWeek(){const currentStart=weekStart(new Date());let selected=eventsInWeek(state.events,currentStart);if(selected.length)return{start:currentStart,events:selected,current:true};const upcoming=[...state.events].filter(event=>dateOf(event.end||event.start)>=currentStart).sort((left,right)=>dateOf(left.start)-dateOf(right.start));if(!upcoming.length)return{start:currentStart,events:[],current:true};const nextStart=weekStart(dateOf(upcoming[0].start));selected=eventsInWeek(state.events,nextStart);return{start:nextStart,events:selected,current:false}}
function resetSlideTimer(){clearInterval(state.slideTimer);if(state.weekEvents.length>1)state.slideTimer=setInterval(()=>showSlide(state.slideIndex+1),6500)}
function imageSrc(event){if(!event.image)return'';if(/^https?:/i.test(event.image))return event.image;return new URL(`../${event.image}`,window.location.href).href}
function showSlide(index){if(!state.weekEvents.length)return;state.slideIndex=(index+state.weekEvents.length)%state.weekEvents.length;const event=state.weekEvents[state.slideIndex];const image=imageSrc(event);$('#weekSlider').innerHTML=`<article class="week-slide" data-feature-id="${event.id}" tabindex="0"><div class="slide-image">${image?`<img src="${esc(image)}" alt="${esc(event.title)}">`:''}<div class="slide-caption"><span class="slide-meta">${fmt(event.start,{weekday:'short',day:'numeric',month:'short'})}</span><h3>${esc(event.title)}</h3></div></div></article>`;const slide=$('[data-feature-id]');slide.onclick=()=>openEvent(event.id);slide.onkeydown=keyEvent=>{if(keyEvent.key==='Enter')openEvent(event.id)};const slideImage=slide.querySelector('img');if(slideImage)slideImage.onerror=()=>slideImage.classList.add('failed');$('#weekProgress').innerHTML=state.weekEvents.map((_,itemIndex)=>`<button class="${itemIndex===state.slideIndex?'active':''}" data-slide="${itemIndex}" aria-label="Show featured event ${itemIndex+1}"></button>`).join('');document.querySelectorAll('[data-slide]').forEach(button=>button.onclick=()=>{showSlide(Number(button.dataset.slide));resetSlideTimer()})}
function renderWeekFeature(){const selection=selectFeatureWeek();state.weekEvents=selection.events;state.slideIndex=0;$('#weekMode').textContent=selection.current?"This week's signals":'Next active week';$('#weekTitle').textContent=`${fmt(selection.start,{day:'numeric',month:'short'})} - ${fmt(addDays(selection.start,6),{day:'numeric',month:'short'})}`;if(!selection.events.length){$('#weekSlider').innerHTML='<div class="empty">No upcoming event signals were found.</div>';$('#weekProgress').innerHTML='';return}showSlide(0);resetSlideTimer()}
function applyFilters(){const query=state.query.toLowerCase();state.filtered=state.events.filter(event=>{const haystack=[event.title,event.location,event.description,...event.topics].join(' ').toLowerCase();return(!query||haystack.includes(query))&&(!state.topic||event.topics.includes(state.topic))&&(state.format==='All'||(state.format==='Free'?event.cost.toLowerCase().includes('free'):event.format===state.format))});render()}
function render(){renderCalendar();renderAgenda();$('#resultCount').textContent=`${String(state.filtered.length).padStart(2,'0')} signals`}
function renderCalendar(){const year=state.month.getFullYear(),month=state.month.getMonth();$('#monthTitle').textContent=new Intl.DateTimeFormat('en-NL',{month:'long',year:'numeric'}).format(state.month);const first=new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(year,month,1-offset);let html='';for(let index=0;index<42;index++){const day=new Date(start);day.setDate(start.getDate()+index);const events=state.filtered.filter(event=>{const eventStart=dateOf(event.start),eventEnd=dateOf(event.end||event.start);eventStart.setHours(0,0,0,0);eventEnd.setHours(23,59,59,999);return day>=eventStart&&day<=eventEnd});html+=`<div class="day ${day.getMonth()!==month?'out':''} ${sameDay(day,new Date())?'today':''}"><span class="num">${day.getDate()}</span>${events.slice(0,2).map(event=>`<button class="event ${event.format==='Online'?'online':''}" data-id="${event.id}" title="${esc(event.title)}">${esc(event.title)}</button>`).join('')}${events.length>2?`<div class="more">+${events.length-2} more</div>`:''}</div>`}$('#calendar').innerHTML=html;document.querySelectorAll('[data-id]').forEach(button=>button.onclick=()=>openEvent(button.dataset.id))}
function renderAgenda(){const events=[...state.filtered].sort((left,right)=>dateOf(left.start)-dateOf(right.start));$('#agenda').innerHTML=events.slice(0,10).map(event=>{const date=dateOf(event.start);return `<article class="agenda-item" data-id="${event.id}" tabindex="0"><div class="agenda-date"><b>${date.getDate()}</b>${date.toLocaleString('en',{month:'short'}).toUpperCase()}</div><div><h3>${esc(event.title)}</h3><p>${esc(event.format)} / ${esc(event.topics.slice(0,2).join(' + '))}</p></div></article>`}).join('')||'<div class="empty">No matching event signals.</div>';document.querySelectorAll('.agenda-item').forEach(item=>{item.onclick=()=>openEvent(item.dataset.id);item.onkeydown=event=>{if(event.key==='Enter')openEvent(item.dataset.id)}})}
function openEvent(id){const event=state.events.find(item=>item.id===id);if(!event)return;$('#detail').innerHTML=`<div class="detail-top"><div><span class="meta">${esc(event.format)} / ${esc(event.topics.join(' + '))}</span><h2>${esc(event.title)}</h2></div><button class="close" aria-label="Close">x</button></div><p>${esc(event.description)}</p><p><strong>${fmt(event.start)}</strong><br>${esc(event.location)} / ${esc(event.cost)} / ${esc(event.language)}</p><a href="${esc(event.url)}" target="_blank" rel="noopener">Open event source &rarr;</a>`;$('#eventDialog').showModal();$('.close').onclick=()=>$('#eventDialog').close()}
function init(){const data=window.CLOUD_CALENDAR_EVENTS;if(!data?.events?.length)throw new Error('Event data unavailable');state.events=data.events;state.filtered=data.events;state.month=dateOf(data.windowStart);state.month.setDate(1);$('#window').textContent=`${fmt(data.windowStart,{day:'numeric',month:'short'})} - ${fmt(data.windowEnd,{day:'numeric',month:'short'})}`;$('#eventCount').textContent=String(data.events.length).padStart(2,'0');$('#nlCount').textContent=String(data.events.filter(event=>event.format==='In person').length).padStart(2,'0');$('#updated').textContent=fmt(data.lastUpdated,{day:'numeric',month:'short'});const topics=[...new Set(data.events.flatMap(event=>event.topics))].sort();$('#topic').innerHTML+=topics.map(topic=>`<option>${esc(topic)}</option>`).join('');renderWeekFeature();applyFilters()}
$('#search').oninput=event=>{state.query=event.target.value;applyFilters()};$('#topic').onchange=event=>{state.topic=event.target.value;applyFilters()};document.querySelectorAll('.chips button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.chips button').forEach(item=>item.classList.remove('active'));button.classList.add('active');state.format=button.dataset.format;applyFilters()});$('#prev').onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1);renderCalendar()};$('#next').onclick=()=>{state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1);renderCalendar()};$('#today').onclick=()=>{const today=new Date();state.month=new Date(today.getFullYear(),today.getMonth(),1);renderCalendar()};$('#slidePrev').onclick=()=>{showSlide(state.slideIndex-1);resetSlideTimer()};$('#slideNext').onclick=()=>{showSlide(state.slideIndex+1);resetSlideTimer()};$('#weekSlider').onmouseenter=()=>clearInterval(state.slideTimer);$('#weekSlider').onmouseleave=resetSlideTimer;$('#eventDialog').onclick=event=>{if(event.target.id==='eventDialog')event.target.close()};init();
